INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23049$nota-0027$m23049$, $m23050$Training and Racing with a Power Meter.pdf$m23050$, $m23051$57$m23051$, $m23052$The TrainingPeaks WKO4 software application, developed in part by the authors, contains a Power Duration Model that uses your power data to estimate FTP. This estimate is called \"modeled FTP\" (mFTP).$m23052$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23053$nota-0027$m23053$, $m23054$Training and Racing with a Power Meter.pdf$m23054$, $m23055$57$m23055$, $m23056$By default, WKO4's mFTP is built upon the last 90 days of data, so if a rider has not done a hard effort in the past 90 days, the model will most likely underestimate mFTP. Furthermore, if a best effort falls off on day 91, mFTP might take a surprisingly large drop on a single day.$m23056$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23057$nota-0027$m23057$, $m23058$nota-0025$m23058$, $m23059$complementa$m23059$, $m23060$é um dos métodos alternativos de estimativa de FTP listados na nota-0025$m23060$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23061$nota-0028$m23061$, $m23062$Training and Racing with a Power Meter.pdf$m23062$, $m23063$65$m23063$, $m23064$some riders were capable of \"superhuman\" efforts, holding 150 percent of FTP for 5 minutes!... These riders required a new set of training levels beyond Level 4, to allow them to train in the correct area of their unique physiology.$m23064$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23065$nota-0028$m23065$, $m23066$Training and Racing with a Power Meter.pdf$m23066$, $m23067$66$m23067$, $m23068$The addition of Level 4a (88–95 percent of FTP), otherwise known as the Sweet Spot, was important... Ultimately, there are nine iLevels (Table 3.5) and there are eight divisions or cut-off points, all of which are determined by the Power Duration model.$m23068$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23069$nota-0028$m23069$, $m23070$nota-0022$m23070$, $m23071$alternativa-a$m23071$, $m23072$modelo concorrente/complementar aos 7 níveis clássicos de Coggan — mesma lógica, mas cortes individualizados por atleta em vez de percentuais fixos de FTP$m23072$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23073$nota-0029$m23073$, $m23074$Training and Racing with a Power Meter.pdf$m23074$, $m23075$63$m23075$, $m23076$average power during mass-start races typically falls within Level 3, but racing at Level 3 is often more stressful than training at Level 3 because racing involves greater variability (and therefore higher peaks) in power.$m23076$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23077$nota-0029$m23077$, $m23078$Training and Racing with a Power Meter.pdf$m23078$, $m23079$63$m23079$, $m23080$due to soft-pedaling and coasting, the average power achieved during a hilly ride or group training session is not equivalent to the same average power achieved during a completely flat ride or solo workout.$m23080$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23081$nota-0029$m23081$, $m23082$nota-0006$m23082$, $m23083$complementa$m23083$, $m23084$mesmo princípio de que o contexto (outdoor/indoor, prova/treino, terreno) afeta a variabilidade de potência independente da média$m23084$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23085$nota-0030$m23085$, $m23086$Training and Racing with a Power Meter.pdf$m23086$, $m23087$63$m23087$, $m23088$there is an inverse relationship between power output and the duration that this power can be sustained. Obviously, power during shorter training sessions or efforts will fall toward the higher end of a given range, whereas power during longer sessions or efforts will fall toward the lower end of a given range.$m23088$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23089$nota-0030$m23089$, $m23090$Training and Racing with a Power Meter.pdf$m23090$, $m23091$64$m23091$, $m23092$a workout consisting of 30 minutes of cycling at Level 1 (a warm-up, for example), 60 minutes of cycling at Level 3, and then another 30 minutes of cycling at Level 1 (a cooldown) would best be described as a Tempo training session, even though the overall average power might fall within Level 2.$m23092$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23093$nota-0030$m23093$, $m23094$nota-0022$m23094$, $m23095$pre-requisito$m23095$, $m23096$usa a classificação de níveis da nota-0022 para ilustrar o problema de classificar pela média geral$m23096$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23097$nota-0033$m23097$, $m23098$Training and Racing with a Power Meter.pdf$m23098$, $m23099$72$m23099$, $m23100$To convert your weight from pounds to kilograms, simply divide your weight by 2.2... take your wattage numbers for each time period and divide them by your weight in kilograms. If you held 423 watts for 5 minutes, for example, you would divide 423 by 75 to get 5.64 watts per kilogram.$m23100$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23101$nota-0033$m23101$, $m23102$Training and Racing with a Power Meter.pdf$m23102$, $m23103$72$m23103$, $m23104$A rider who weighs 200 pounds and produces 350 watts up a hill... will be able to ride side by side with a rider who weighs 125 pounds but is producing only 218 watts... the power-to-weight ratio is the same—3.85 watts per kilogram.$m23104$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23105$nota-0037$m23105$, $m23106$Training and Racing with a Power Meter.pdf$m23106$, $m23107$79$m23107$, $m23108$The Power Duration Curve is derived from your Mean Maximal Power, which captures your actual best power outputs for each and every time... The Power Duration Curve is a mathematically calculated curve of \"best fit\" along the Mean Maximal Power Curve.$m23108$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23109$nota-0037$m23109$, $m23110$Training and Racing with a Power Meter.pdf$m23110$, $m23111$80$m23111$, $m23112$first look at any areas where your effort falls below the PDC. This could mean you haven't done an all-out effort for that specific time period or it could indicate a physiological weakness to be improved.$m23112$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23113$nota-0037$m23113$, $m23114$nota-0031$m23114$, $m23115$complementa$m23115$, $m23116$generaliza o Power Profile (4 pontos discretos) para uma curva contínua ao longo de todas as durações$m23116$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23117$nota-0045$m23117$, $m23118$Training and Racing with a Power Meter.pdf$m23118$, $m23119$110$m23119$, $m23120$Functional Reserve Capacity (FRC) is the total amount of work that you can do above your FTP. In theory a cyclist will utilize all of his or her FRC when riding to failure at a supra-FTP intensity.$m23120$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m23121$nota-0045$m23121$, $m23122$Training and Racing with a Power Meter.pdf$m23122$, $m23123$111$m23123$, $m23124$Joe Athlete's Level 6 (Anaerobic Capacity) based on the Coggan Classic levels is 121–150 percent of Joe's FTP... riding between 351 and 435 watts... Using the Power Duration Curve... at 28 seconds, he has sustained just under 700 watts, and at 1:33, he averaged 471 watts.$m23124$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m23125$nota-0045$m23125$, $m23126$nota-0028$m23126$, $m23127$complementa$m23127$, $m23128$FRC é a base fisiológica dos iLevels 5, 6 e 7a definidos na Tabela 3.5 (nota-0028)$m23128$)
